"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import { AlertTriangle, Check, ExternalLink, FilePenLine, FlaskConical, Loader2, Plus, RefreshCw, Send, Users } from "lucide-react";
import { useBrand } from "@/components/brand-context";
import { useEditorialPipeline } from "@/components/editorial-pipeline-context";
import { OperationalDataGrid, type OperationalGridColumn } from "@/components/editorial/operational-data-grid";
import { DataOriginBadge, EmptyPipelineState, HumanDecisionRequired, ProvenancePanel, ProviderNotConfiguredState, VersionBadge } from "@/components/editorial/pipeline-ui";
import { adaptLegacyBrand } from "@/lib/editorial/adapters";
import { approvedArticleVersions, type OperationalPublication, type PlannerItem, type RadarItem } from "@/lib/editorial/operational-flow";
import type { VersionEnvelope, ArticleDNA, ContentDocument } from "@/lib/arquiteto/contracts";
import { ProfessionalWriter } from "@/components/editorial/professional-writer";
import { WorkflowImportDialog, WorkflowStatusBadge } from "@/components/editorial/workflow-status";
import { HistoryControls } from "@/components/editorial/history-controls";
import { useLocalHistory } from "@/components/editorial/use-local-history";

const btn = "inline-flex h-7 items-center rounded border border-indigo-900 bg-indigo-950/20 px-2.5 text-[10px] font-bold text-indigo-300 hover:bg-indigo-950/50 disabled:cursor-not-allowed disabled:opacity-40";
const field = "h-8 w-full rounded border border-slate-800 bg-black px-2 text-[11px] text-slate-200 outline-none focus:border-indigo-600";
const card = "rounded-lg border border-slate-900 bg-[#0b0c10] p-4";
const Field = ({ label, value }: { label: string; value: unknown }) => <div><dt className="text-[8px] font-bold uppercase tracking-wider text-slate-600">{label}</dt><dd className="mt-1 break-words text-[10px] text-slate-300">{value === null || value === undefined || value === "" ? "Não informado" : String(value)}</dd></div>;

function ModuleHeader({ title, description, actions }: { title: string; description: string; actions?: React.ReactNode }) {
  const { activeBrand } = useBrand(); const pipeline = useEditorialPipeline();
  return <header className="sticky top-0 z-40 flex h-12 items-center justify-between border-b border-slate-900 bg-[#07080b]/95 px-3 backdrop-blur"><div className="min-w-0"><p className="truncate text-[8px] font-bold uppercase tracking-[.2em] text-indigo-400">{activeBrand?.nome || "Sem marca"}</p><div className="flex items-baseline gap-2"><h1 className="text-sm font-bold text-white">{title}</h1><p className="hidden text-[9px] text-slate-600 md:block">{description}</p></div></div><div className="flex items-center gap-1">{actions}<button className={btn} onClick={() => void pipeline.reload()}><RefreshCw className="mr-1 h-3 w-3"/>Atualizar dados</button></div></header>;
}

function useReadyPipeline() {
  const pipeline = useEditorialPipeline();
  if (pipeline.loading && !pipeline.snapshot) return { pipeline, state: <div className="flex min-h-[50vh] items-center justify-center text-xs text-slate-500"><Loader2 className="mr-2 h-4 w-4 animate-spin"/>Carregando…</div> };
  if (!pipeline.snapshot) return { pipeline, state: <EmptyPipelineState title="Marca sem dados" description={pipeline.error || "Selecione uma marca autorizada."}/> };
  return { pipeline, state: null };
}

function sessionId(session: ReturnType<typeof useSession>["data"]) { return session?.user?.email || session?.user?.id || "usuario-local"; }

export function BrandPage({ initialSection = "visao" }: { initialSection?: string }) {
  const { activeBrand, refreshBrands, userRole, selectedBrandId } = useBrand(); const { data: session } = useSession(); const { pipeline, state } = useReadyPipeline();
  const [section, setSection] = useState(initialSection); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  const [inviteOpen, setInviteOpen] = useState(false); const [invite, setInvite] = useState({ email: "", role: "writer", expiresInDays: 7, modules: ["redator"], actions: ["view", "edit", "comment"] });
  const [form, setForm] = useState({ nome: activeBrand?.nome || "", site_url: activeBrand?.site_url || "", nicho: activeBrand?.nicho || "", localizacao: activeBrand?.localizacao || "", dna_diretrizes: activeBrand?.dna_diretrizes || "" });
  useEffect(() => { const timer = window.setTimeout(() => { if (activeBrand) setForm({ nome: activeBrand.nome || "", site_url: activeBrand.site_url || "", nicho: activeBrand.nicho || "", localizacao: activeBrand.localizacao || "", dna_diretrizes: activeBrand.dna_diretrizes || "" }); }, 0); return () => window.clearTimeout(timer); }, [activeBrand]);
  if (state || !pipeline.snapshot || !activeBrand) return state;
  const legacy = adaptLegacyBrand(pipeline.snapshot); const sections = [["visao", "Visão geral"], ["dna", "DNA"], ["materiais", "Materiais"], ["skills", "Skills e prompts"], ["equipe", "Equipe"], ["configuracoes", "Configurações"]];
  const save = async () => { setSaving(true); setMessage(""); try { const response = await fetch("/api/marcas", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: activeBrand.id, ...form, silos_existentes: activeBrand.silos_existentes }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Erro ao salvar."); await refreshBrands(); setMessage("Marca atualizada."); } catch (error) { setMessage(error instanceof Error ? error.message : "Erro ao salvar."); } finally { setSaving(false); } };
  const sendInvite = async () => { setMessage(""); const expiresAt = new Date(Date.now() + invite.expiresInDays * 86400000).toISOString(); const input = { email: invite.email, role: invite.role, expiresAt, permissions: invite.modules.map(module => ({ module, actions: invite.actions })), createdBy: sessionId(session) };
    try { const response = await fetch("/api/editorial/invitations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId: selectedBrandId, ...input }) }); const body = await response.json();
      if (!response.ok && body.code === "persistence_unavailable") { pipeline.createInvitation(input as Parameters<typeof pipeline.createInvitation>[0]); setInviteOpen(false); setMessage("Convite mantido apenas localmente; a migration de persistência ainda não foi aplicada e nenhum e-mail foi enviado."); return; }
      if (!response.ok) throw new Error(body.error || "Convite inválido."); pipeline.addInvitation(body.invitation); setInviteOpen(false); setMessage(body.message);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Erro ao criar convite."); } };
  return <><ModuleHeader title="Marca" description="Organização, BrandDNA, materiais, equipe e configurações."/><main className="p-3"><div className="mb-3 flex flex-wrap gap-1">{sections.map(([id, label]) => <button key={id} onClick={() => setSection(id)} className={`${btn} ${section === id ? "border-indigo-500 text-white" : ""}`}>{label}</button>)}</div>
    {message && <p className="mb-3 rounded border border-amber-900/40 bg-amber-950/20 p-2 text-[10px] text-amber-300">{message}</p>}
    {section === "visao" && <div className="grid gap-3 md:grid-cols-4"><Metric label="Keywords" value={pipeline.snapshot.keywords.length}/><Metric label="ArticleDNAs aprovados" value={approvedArticleVersions(pipeline.articleVersions, pipeline.versionEvents).length}/><Metric label="Radar" value={pipeline.radarItems.length}/><Metric label="Publicações" value={pipeline.operationalPublications.length + pipeline.snapshot.briefings.length}/><section className={`${card} md:col-span-4`}><h2 className="text-xs font-bold">Fluxo operacional</h2><p className="mt-2 text-[10px] text-slate-500">Minerador → Arquiteto → Radar → Planejador → Redator → Publicações</p></section></div>}
    {section === "dna" && <div className="grid gap-3 lg:grid-cols-2"><section className={card}><div className="flex justify-between"><h2 className="text-xs font-bold">Cadastro real</h2><DataOriginBadge origin="real"/></div><dl className="mt-3 grid grid-cols-2 gap-3"><Field label="Nicho" value={activeBrand.nicho}/><Field label="Localização" value={activeBrand.localizacao}/><Field label="Site" value={activeBrand.site_url}/><Field label="Silos" value={pipeline.snapshot.silos.length}/></dl></section><section className={card}><div className="flex justify-between"><h2 className="text-xs font-bold">Diretrizes legadas</h2><DataOriginBadge origin="legacy"/></div><div className="mt-2"><VersionBadge version="legacy" hash={legacy.contentHash}/></div><p className="mt-3 whitespace-pre-wrap text-[10px] text-slate-400">{legacy.rawGuidelines || "Não informado"}</p><p className="mt-2 text-[9px] text-amber-400">Não é BrandDNA estruturado ou aprovado.</p></section></div>}
    {section === "materiais" && <LocalCollection title="Materiais da marca" count={pipeline.materials.length} description="Contratos locais; persistência aguarda migration."/>}
    {section === "skills" && <div className="grid gap-3 md:grid-cols-2"><LocalCollection title="Skills" count={pipeline.skills.length} description="Regras reutilizáveis aprovadas pela marca."/><LocalCollection title="Prompts" count={pipeline.prompts.length} description="Prompts permanentes ou específicos de artigo."/></div>}
    {section === "equipe" && <div className="space-y-3"><section className={card}><div className="flex items-center justify-between"><div><h2 className="text-xs font-bold">Equipe e acessos</h2><p className="mt-1 text-[10px] text-slate-500">Permissões são granulares por módulo e ação.</p></div><button className={btn} onClick={() => setInviteOpen(value => !value)}><Users className="mr-1 h-3 w-3"/>Convidar colaborador</button></div>{inviteOpen && <div className="mt-3 grid gap-2 border-t border-slate-850 pt-3 md:grid-cols-4"><input className={field} type="email" placeholder="email@empresa.com" value={invite.email} onChange={event => setInvite(current => ({ ...current, email: event.target.value }))}/><select className={field} value={invite.role} onChange={event => setInvite(current => ({ ...current, role: event.target.value }))}>{["strategist", "analyst", "planner", "writer", "editor", "reviewer", "medical_reviewer", "publisher", "viewer", "external_collaborator"].map(role => <option key={role}>{role}</option>)}</select><select className={field} value={invite.modules[0]} onChange={event => setInvite(current => ({ ...current, modules: [event.target.value] }))}>{["marca", "minerador", "arquiteto", "radar", "planejador", "redator", "publicacoes"].map(module => <option key={module}>{module}</option>)}</select><button className={btn} onClick={() => void sendInvite()} disabled={!invite.email}>Criar convite pendente</button><label className="md:col-span-4 text-[9px] text-slate-500">Ações<div className="mt-1 flex flex-wrap gap-2">{["view", "comment", "edit", "write", "review", "approve", "export", "publish"].map(action => <label key={action} className="flex items-center gap-1"><input type="checkbox" checked={invite.actions.includes(action)} onChange={event => setInvite(current => ({ ...current, actions: event.target.checked ? [...current.actions, action] : current.actions.filter(item => item !== action) }))}/>{action}</label>)}</div></label></div>}</section>
      {pipeline.invitations.length ? <div className="overflow-x-auto rounded border border-slate-900"><table className="w-full text-[10px]"><thead className="bg-slate-950 text-slate-600"><tr><th className="p-2 text-left">E-mail</th><th>Papel</th><th>Escopo</th><th>Validade</th><th>Status</th><th>Ações</th></tr></thead><tbody>{pipeline.invitations.map(item => <tr key={item.id} className="border-t border-slate-900"><td className="p-2">{item.email}</td><td className="text-center">{item.role}</td><td className="text-center">{item.permissions.map(permission => `${permission.module}: ${permission.actions.join(", ")}`).join(" · ")}</td><td className="text-center">{new Date(item.expiresAt).toLocaleDateString("pt-BR")}</td><td className="text-center">{item.status} · e-mail não enviado</td><td className="space-x-1 p-2 text-right"><button className={btn} disabled={item.status !== "pending"} onClick={() => pipeline.updateInvitationStatus(item.id, "cancelled")}>Cancelar</button><button className={btn} onClick={() => pipeline.updateInvitationStatus(item.id, item.status === "suspended" ? "pending" : "suspended")}>{item.status === "suspended" ? "Reativar" : "Suspender"}</button><button className={btn} onClick={() => pipeline.updateInvitationStatus(item.id, "revoked")}>Revogar</button></td></tr>)}</tbody></table></div> : <EmptyPipelineState title="Nenhum convite" description="O adaptador de desenvolvimento não envia e-mail e mantém convites apenas nesta sessão."/>}<HumanDecisionRequired>Convites foram validados no servidor, mas ainda não persistem. O papel “cliente” continua como responsável legado da própria marca.</HumanDecisionRequired></div>}
    {section === "configuracoes" && <section className={`${card} max-w-4xl`}><div className="flex justify-between"><h2 className="text-xs font-bold">Configurações da empresa</h2><span className="text-[9px] text-slate-600">Acesso: {userRole}</span></div><div className="mt-4 grid gap-3 md:grid-cols-2">{(["nome", "site_url", "nicho", "localizacao"] as const).map(key => <label key={key} className="text-[9px] text-slate-500">{key}<input value={form[key]} onChange={event => setForm(current => ({ ...current, [key]: event.target.value }))} className={`${field} mt-1`}/></label>)}<label className="md:col-span-2 text-[9px] text-slate-500">Diretrizes<textarea value={form.dna_diretrizes} onChange={event => setForm(current => ({ ...current, dna_diretrizes: event.target.value }))} rows={8} className="mt-1 w-full rounded border border-slate-800 bg-black p-2 text-xs text-slate-200"/></label></div><button disabled={saving} onClick={() => void save()} className={`${btn} mt-3`}><Check className="mr-1 h-3 w-3"/>{saving ? "Salvando…" : "Salvar configuração existente"}</button></section>}
  </main></>;
}

function ImportPanel<T extends { id: string }>({ title, rows, label, disabled, status, onClose, onImport }: { title: string; rows: T[]; label: (row: T) => React.ReactNode; disabled?: (row: T) => boolean; status?: (row: T) => string; onClose: () => void; onImport: (ids: string[]) => void }) {
  const isDisabled = disabled || ((row: T) => Boolean((row as T & { alreadyImported?: boolean }).alreadyImported));
  const rowStatus = status || ((row: T) => (row as T & { importStatus?: string }).importStatus || "approved");
  return <WorkflowImportDialog open title={title} description="Todos os aprovados da etapa anterior aparecem abaixo; os já importados permanecem visíveis e bloqueados." rows={rows} label={label} disabled={isDisabled} status={rowStatus} onClose={onClose} onImport={onImport}/>;
}

export function RadarPage() {
  const { data: session } = useSession(); const { selectedBrandId } = useBrand(); const { pipeline, state } = useReadyPipeline(); const [picker, setPicker] = useState(false); const [notice, setNotice] = useState("");
  const historyValue = useMemo(() => ({ radarItems: pipeline.radarItems, serpRecords: pipeline.serpRecords, productEvidence: pipeline.productEvidence }), [pipeline.radarItems, pipeline.serpRecords, pipeline.productEvidence]);
  const history = useLocalHistory("radar", historyValue, snapshot => pipeline.restoreOperationalSnapshot("radar", snapshot), 30, selectedBrandId || "sem-marca");
  if (state || !pipeline.snapshot) return state;
  const approved = approvedArticleVersions(pipeline.articleVersions, pipeline.versionEvents);
  const columns: OperationalGridColumn<RadarItem>[] = [
    { id: "title", header: "Artigo", value: row => row.title, pinned: "left", sortable: true, width: 240, render: row => <div><strong className="block truncate text-slate-200">{row.title}</strong><span className="text-[9px] text-slate-600">{row.articleDnaVersionId.slice(0, 12)}…</span></div> },
    { id: "slug", header: "Slug", value: row => row.slug, sortable: true, width: 180, render: row => <code>/{row.slug}</code> },
    { id: "siloId", header: "Silo", value: row => row.siloId, sortable: true }, { id: "principalKeywordId", header: "Keyword principal", value: row => pipeline.snapshot!.keywords.find(keyword => keyword.id === row.principalKeywordId)?.keyword || row.principalKeywordId, width: 180 },
    { id: "keywordDnas", header: "KeywordDNAs", value: row => pipeline.articleVersions[row.articleId]?.payload.keywordReferences.length || 0, width: 105 },
    { id: "articleDna", header: "ArticleDNA", value: row => row.articleDnaVersionId, render: row => <VersionBadge version={pipeline.articleVersions[row.articleId]?.versionNumber || 1} hash={row.articleDnaContentHash}/>, width: 95 },
    { id: "siloDna", header: "SiloDNA", value: row => pipeline.siloVersions[row.siloId]?.versionId || "pendente", render: row => pipeline.siloVersions[row.siloId] ? <VersionBadge version={pipeline.siloVersions[row.siloId].versionNumber} hash={pipeline.siloVersions[row.siloId].contentHash}/> : <span className="text-slate-600">pendente</span>, width: 90 },
    { id: "format", header: "Formato", value: row => row.format, filterOptions: [...new Set(pipeline.radarItems.map(item => item.format))].map(value => ({ label: value, value })) },
    { id: "serp", header: "SERP", value: row => pipeline.serpRecords.some(record => record.input.articleId === row.articleId) ? "simulada" : "não configurada" },
    { id: "sources", header: "Fontes", value: row => pipeline.externalSources.filter(source => source.articleId === row.articleId).length },
    { id: "products", header: "Produtos", value: row => pipeline.productEvidence.filter(evidence => evidence.evidenceId.includes(row.articleId)).length },
    { id: "internal", header: "Conflito interno", value: () => "determinístico" }, { id: "external", header: "Similaridade externa", value: () => "não integrada", width: 160 },
    { id: "state", header: "Status", value: row => row.state, render: row => <WorkflowStatusBadge status={row.state}/>, sortable: true, filterOptions: ["research_pending", "researching", "needs_review", "conflicts", "awaiting_approval", "approved", "sent_planner"].map(value => ({ label: value, value })), width: 170 },
  ];
  const simulate = async (row: RadarItem, capture = true) => { if (capture) history.capture(`Processar SERP de ${row.title}`); const keyword = pipeline.snapshot!.keywords.find(item => item.id === row.principalKeywordId)?.keyword || row.principalKeywordId; await pipeline.simulateSerp(row.articleId, keyword, pipeline.snapshot!.brand.localizacao || "Brasil"); setNotice("Dados simulados adicionados e isolados. Eles não alteraram a aprovação do workflow."); };
  const transition = (ids: string[], target: RadarItem["state"], label: string) => { history.capture(label); pipeline.updateRadarState(ids, target); };
  const approve = (ids: string[]) => { const eligible = pipeline.radarItems.filter(item => ids.includes(item.id) && item.state === "awaiting_approval").map(item => item.id); transition(eligible, "approved", `Aprovar ${eligible.length} artigo(s) no Radar`); };
  const sendToPlanner = (ids: string[]) => { history.capture(`Enviar ${ids.length} artigo(s) ao Planejador`); return pipeline.importApprovedToPlanner(ids); };
  const importable = approved.map(version => { const alreadyImported = pipeline.radarItems.some(item => item.articleId === version.payload.articleId); return { ...version, id: version.versionId, alreadyImported, importStatus: alreadyImported ? "sent_radar" : "approved" }; });
  return <div className="flex h-screen min-h-0 flex-col">{notice && <div className="shrink-0 border-b border-amber-900/40 bg-amber-950/20 px-3 py-1.5 text-[9px] text-amber-300">{notice}</div>}<OperationalDataGrid title="Radar" description="Artigos com DNAs acumulados, SERP, evidências e originalidade." module="radar" userId={sessionId(session)} brandId={selectedBrandId} rows={pipeline.radarItems} columns={columns} toolbar={<><HistoryControls entries={history.entries} canUndo={history.canUndo} canRedo={history.canRedo} onUndo={history.undo} onRedo={history.redo} onRestore={history.restore} compact/><button className={btn} onClick={() => setPicker(true)}><Plus className="mr-1 h-3 w-3"/>Importar do Arquiteto</button><button className={btn} onClick={() => void pipeline.reload()}><RefreshCw className="mr-1 h-3 w-3"/>Atualizar</button></>} emptyTitle="Nenhum artigo importado. Use “Importar do Arquiteto”." bulkActions={[{ label: "Processar SERP selecionada", onClick: async rows => { history.capture(`Processar SERP de ${rows.length} artigo(s)`); for (const row of rows) await simulate(row); } }, { label: "Enviar para aprovação", onClick: rows => { const ids = rows.filter(row => ["research_pending", "needs_review"].includes(row.state)).map(row => row.id); transition(ids, "awaiting_approval", `Enviar ${ids.length} artigo(s) para aprovação`); } }, { label: "Aprovar selecionados", onClick: rows => approve(rows.map(row => row.id)) }, { label: "Enviar ao Planejador", onClick: rows => { const result = sendToPlanner(rows.filter(row => row.state === "approved").map(row => row.id)); setNotice(`${result.imported} item(ns) enviado(s); ${result.skipped} ignorado(s).`); } }]} renderActions={row => <div className="flex justify-end gap-1">{["research_pending", "needs_review"].includes(row.state) && <button className={btn} onClick={() => transition([row.id], "awaiting_approval", `Revisar ${row.title}`)}>Revisado</button>}{row.state === "awaiting_approval" && <button className={btn} onClick={() => approve([row.id])}>Aprovar</button>}{row.state === "approved" && <button className={btn} onClick={() => sendToPlanner([row.id])}><Send className="h-3 w-3"/></button>}<button className={btn} onClick={() => void simulate(row)}><FlaskConical className="h-3 w-3"/></button><Link className={btn} href={`/arquiteto?articleId=${row.articleId}`}>Abrir</Link></div>} renderExpanded={row => <RadarDetail row={row} article={pipeline.articleVersions[row.articleId]} pipeline={pipeline}/>}/>{picker && <ImportPanel title="Importar artigos aprovados" rows={importable} label={version => `${version.payload.promise} · /${version.payload.suggestedSlug} · ${version.payload.mainIntent}`} onClose={() => setPicker(false)} onImport={ids => { const selectedVersions = importable.filter(version => ids.includes(version.id)); history.capture(`Importar ${selectedVersions.length} artigo(s) do Arquiteto`); const result = pipeline.importApprovedToRadar(selectedVersions.map(version => version.payload.articleId)); setNotice(`${result.imported} importado(s); ${result.skipped} já existente(s) ou inválido(s).`); setPicker(false); }}/>}</div>;
}

function RadarDetail({ row, article, pipeline }: { row: RadarItem; article?: VersionEnvelope<ArticleDNA>; pipeline: ReturnType<typeof useEditorialPipeline> }) {
  const serp = pipeline.serpRecords.find(record => record.input.articleId === row.articleId);
  return <div className="grid gap-3 lg:grid-cols-3"><section className={card}><h3 className="text-[10px] font-bold">ArticleDNA e referências</h3>{article ? <dl className="mt-2 space-y-2"><Field label="Intenção" value={article.payload.mainIntent}/><Field label="Cobertura" value={article.payload.coverage.join(" · ")}/><Field label="Keywords" value={article.payload.keywordReferences.length}/><Field label="Fronteira" value={article.payload.antiCannibalizationBoundary}/></dl> : <p className="mt-2 text-[10px] text-red-400">Versão ausente.</p>}</section><section className={card}><h3 className="text-[10px] font-bold">SERP e evidências</h3>{serp ? <><DataOriginBadge origin={serp.origin}/><dl className="mt-2 space-y-2"><Field label="Intenção dominante" value={serp.snapshot?.dominantIntent}/><Field label="Perguntas" value={serp.snapshot?.questions.join(" · ")}/><Field label="Lacunas" value={serp.snapshot?.gaps.join(" · ")}/></dl></> : <ProviderNotConfiguredState/>}</section><section className={card}><h3 className="text-[10px] font-bold">Originalidade</h3><p className="mt-2 text-[10px] text-slate-500">Conflito interno: funcional.</p><p className="mt-1 text-[10px] text-slate-500">Similaridade externa: aguardando provedor.</p><p className="mt-1 text-[10px] text-slate-500">Originalidade estratégica: decisão humana.</p></section></div>;
}

export function PlannerPage() {
  const { data: session } = useSession(); const router = useRouter(); const { selectedBrandId } = useBrand(); const { pipeline, state } = useReadyPipeline(); const [picker, setPicker] = useState(false); const [notice, setNotice] = useState("");
  const historyValue = useMemo(() => ({ plannerItems: pipeline.plannerItems, contentPlans: pipeline.contentPlans, internalLinks: pipeline.internalLinks, externalSources: pipeline.externalSources }), [pipeline.plannerItems, pipeline.contentPlans, pipeline.internalLinks, pipeline.externalSources]);
  const history = useLocalHistory("planejador", historyValue, snapshot => pipeline.restoreOperationalSnapshot("planejador", snapshot), 30, selectedBrandId || "sem-marca");
  if (state) return state; const available = pipeline.radarItems.filter(item => ["approved", "sent_planner"].includes(item.state)).map(item => { const alreadyImported = item.state === "sent_planner" || pipeline.plannerItems.some(plan => plan.articleId === item.articleId); return { ...item, alreadyImported, importStatus: alreadyImported ? "sent_planner" : "approved" }; });
  const columns: OperationalGridColumn<PlannerItem>[] = [
    { id: "title", header: "Artigo", value: row => row.title, pinned: "left", sortable: true, width: 250 }, { id: "slug", header: "Slug", value: row => row.slug, width: 190, render: row => <code>/{row.slug}</code> },
    { id: "siloId", header: "Silo", value: row => row.siloId, sortable: true }, { id: "format", header: "Formato", value: row => row.format }, { id: "intent", header: "Intenção", value: row => row.intent, width: 160 },
    { id: "keywordDnas", header: "KeywordDNAs", value: row => pipeline.articleVersions[row.articleId]?.payload.keywordReferences.length || 0, width: 105 },
    { id: "articleDna", header: "ArticleDNA", value: row => pipeline.articleVersions[row.articleId]?.versionId || "ausente", render: row => pipeline.articleVersions[row.articleId] ? <VersionBadge version={pipeline.articleVersions[row.articleId].versionNumber} hash={pipeline.articleVersions[row.articleId].contentHash}/> : <span className="text-red-400">ausente</span>, width: 95 },
    { id: "siloDna", header: "SiloDNA", value: row => pipeline.siloVersions[row.siloId]?.versionId || "pendente", render: row => pipeline.siloVersions[row.siloId] ? <VersionBadge version={pipeline.siloVersions[row.siloId].versionNumber} hash={pipeline.siloVersions[row.siloId].contentHash}/> : <span className="text-slate-600">pendente</span>, width: 90 },
    { id: "serpLoad", header: "Carga Radar", value: row => pipeline.serpRecords.filter(record => record.input.articleId === row.articleId).length + pipeline.externalSources.filter(source => source.articleId === row.articleId).length, width: 95 },
    { id: "outline", header: "Outline", value: row => pipeline.contentPlans[`plan:${row.articleId}`]?.payload.approvedOutline.length || 0 }, { id: "links", header: "Links internos", value: row => pipeline.internalLinks.filter(link => link.sourceArticleId === row.articleId).length },
    { id: "sources", header: "Fontes externas", value: row => pipeline.externalSources.filter(source => source.articleId === row.articleId).length }, { id: "pending", header: "Pendências", value: row => pipeline.contentPlans[`plan:${row.articleId}`]?.payload.humanPendingDecisions.length || 0 },
    { id: "state", header: "Status", value: row => row.state, render: row => <WorkflowStatusBadge status={row.state}/>, sortable: true, filterOptions: ["draft", "planning", "pending", "awaiting_review", "approved", "sent_writer"].map(value => ({ label: value, value })), width: 170 },
  ];
  const prepare = async (ids: string[]) => { history.capture(`Preparar ContentPlan de ${ids.length} artigo(s)`); await pipeline.preparePlannerItems(ids, sessionId(session)); };
  const approvePlans = (ids: string[]) => { history.capture(`Aprovar ${ids.length} ContentPlan(s)`); pipeline.approvePlannerItems(ids); };
  const write = async (row: PlannerItem) => { try { history.capture(`Enviar ${row.title} ao Redator`); const result = await pipeline.startWriting(row.id); router.push(`/redator?articleId=${encodeURIComponent(result.articleId)}`); } catch (error) { setNotice(error instanceof Error ? error.message : "Não foi possível abrir o Redator."); } };
  return <div className="flex h-screen min-h-0 flex-col">{notice && <div className="shrink-0 border-b border-amber-900/40 bg-amber-950/20 px-3 py-1.5 text-[9px] text-amber-300">{notice}</div>}<OperationalDataGrid title="Planejador" description="Artigos enriquecidos pelo Radar, agora com ContentPlan, links, fontes e imagens." module="planejador" userId={sessionId(session)} brandId={selectedBrandId} rows={pipeline.plannerItems} columns={columns} toolbar={<><HistoryControls entries={history.entries} canUndo={history.canUndo} canRedo={history.canRedo} onUndo={history.undo} onRedo={history.redo} onRestore={history.restore} compact/><button className={btn} onClick={() => setPicker(true)}><Plus className="mr-1 h-3 w-3"/>Importar do Radar</button><button className={btn} onClick={() => void pipeline.reload()}><RefreshCw className="mr-1 h-3 w-3"/>Atualizar</button></>} emptyTitle="Nenhum artigo importado do Radar." bulkActions={[{ label: "Preparar ContentPlan", onClick: rows => void prepare(rows.filter(row => row.state === "draft").map(row => row.id)) }, { label: "Aprovar selecionados", onClick: rows => approvePlans(rows.map(row => row.id)) }]} renderActions={row => <div className="flex justify-end gap-1">{row.state === "draft" && <button className={btn} onClick={() => void prepare([row.id])}>Planejar</button>}{row.state === "awaiting_review" && <button className={btn} onClick={() => approvePlans([row.id])}>Aprovar</button>}{["approved", "sent_writer"].includes(row.state) && <button className={btn} onClick={() => void write(row)}><FilePenLine className="mr-1 h-3 w-3"/>Redigir</button>}<Link className={btn} href={`/radar?articleId=${row.articleId}`}>Radar</Link></div>} renderExpanded={row => { const plan = pipeline.contentPlans[`plan:${row.articleId}`]; return <div className="grid gap-3 lg:grid-cols-3"><section className={card}><h3 className="text-[10px] font-bold">Referências exatas acumuladas</h3><dl className="mt-2 space-y-2"><Field label="ArticleDNA" value={plan?.payload.articleDnaRef.versionId}/><Field label="SiloDNA" value={plan?.payload.siloDnaRef.versionId}/><Field label="KeywordDNAs" value={plan?.payload.keywordDnaRefs.length}/><Field label="SERP/evidências" value={(plan?.payload.serpEvidenceRefs.length || 0) + (plan?.payload.productEvidenceRefs.length || 0)}/></dl></section><section className={`${card} lg:col-span-2`}><h3 className="text-[10px] font-bold">Outline</h3>{plan?.payload.approvedOutline.map(section => <div key={section.id} className="mt-2 border-l border-indigo-800 pl-2 text-[10px]"><strong>{section.heading}</strong><p className="text-slate-500">{section.objective}</p></div>) || <p className="mt-2 text-[10px] text-slate-600">Prepare o plano para gerar o outline local.</p>}</section></div>; }}/>{picker && <ImportPanel title="Importar aprovados do Radar" rows={available} label={row => `${row.title} · /${row.slug} · ${row.intent}`} onClose={() => setPicker(false)} onImport={ids => { history.capture(`Importar ${ids.length} artigo(s) do Radar`); const result = pipeline.importApprovedToPlanner(ids); setNotice(`${result.imported} importado(s); ${result.skipped} ignorado(s).`); setPicker(false); }}/>}</div>;
}

export function WriterPage({ initialArticleId = null, initialDocumentId = null }: { initialArticleId?: string | null; initialDocumentId?: string | null }) {
  return <ProfessionalWriter initialArticleId={initialArticleId} initialDocumentId={initialDocumentId}/>;
}

/** @deprecated Mantido temporariamente apenas para reversao visual da sprint anterior. */
export function LegacyWriterPrototype({ initialArticleId = null }: { initialArticleId?: string | null }) {
  const router = useRouter(); const { pipeline, state } = useReadyPipeline(); const [leftOpen, setLeftOpen] = useState(true); const [rightOpen, setRightOpen] = useState(true); const [fullscreen, setFullscreen] = useState(false);
  const requestedId = initialArticleId;
  if (state) return state; const documents = Object.values(pipeline.documents); const document = documents.find(item => item.articleDnaRef.entityId === requestedId) || documents[0];
  if (!document) return <><ModuleHeader title="Redator" description="Documento editorial e Guardião."/><main className="p-4"><EmptyPipelineState title="Nenhum documento" description="Aprove um ContentPlan e use “Redigir artigo” no Planejador." action={<Link className={btn} href="/planejador">Abrir Planejador</Link>}/></main></>;
  const articleId = document.articleDnaRef.entityId; const publication = pipeline.operationalPublications.find(item => item.documentId === document.id); const wordCount = document.blocks.reduce((sum, block) => sum + ("text" in block ? block.text.split(/\s+/).filter(Boolean).length : 0), 0);
  return <div className={`${fullscreen ? "fixed inset-0 z-[100] bg-[#07080b]" : "min-h-screen"} flex flex-col`}><ModuleHeader title="Redator" description={`${document.title} · rascunho local`} actions={<><button className={btn} onClick={() => setLeftOpen(value => !value)}>Fundamentos</button><button className={btn} onClick={() => setRightOpen(value => !value)}>Guardião</button><button className={btn} onClick={() => setFullscreen(value => !value)}>{fullscreen ? "Sair da tela cheia" : "Tela cheia"}</button></>}/><div className="border-b border-amber-900/40 bg-amber-950/20 px-3 py-2 text-[10px] text-amber-200"><AlertTriangle className="mr-1 inline h-3 w-3"/><strong>Editor rico bloqueado:</strong> Tiptap não está instalado. Este documento e seus vínculos são reais no estado local, mas os controles de edição permanecem desabilitados para não simular um editor profissional.</div><div className="flex items-center gap-1 overflow-x-auto border-b border-slate-850 bg-[#0b0c10] p-2">{["Desfazer", "Refazer", "H1", "H2", "H3", "H4", "Parágrafo", "Negrito", "Itálico", "Sublinhado", "Tachado", "Lista", "Tabela", "Link", "Link interno", "Fonte", "CTA", "Produto", "Comparação", "Imagem", "Comentário"].map(action => <button key={action} disabled className={btn}>{action}</button>)}<span className="ml-auto whitespace-nowrap text-[9px] text-slate-600">{wordCount} palavras · não salvo remotamente</span></div><main className={`grid min-h-0 flex-1 ${leftOpen && rightOpen ? "xl:grid-cols-[260px_minmax(780px,900px)_300px]" : leftOpen ? "xl:grid-cols-[260px_minmax(780px,900px)]" : rightOpen ? "xl:grid-cols-[minmax(780px,900px)_300px]" : "xl:grid-cols-[minmax(780px,900px)]"} justify-center gap-3 overflow-auto bg-[#111218] p-3`}>
    {leftOpen && <aside className="h-fit rounded border border-slate-800 bg-[#090a0e] p-3"><h2 className="text-[10px] font-bold uppercase text-slate-500">Fundamentos</h2><dl className="mt-3 space-y-2"><Field label="ContentPlan" value={document.contentPlanRef.versionId}/><Field label="ArticleDNA" value={document.articleDnaRef.versionId}/><Field label="SiloDNA" value={document.siloDnaRef.versionId}/><Field label="KeywordDNAs" value={document.keywordDnaRefs.length}/><Field label="Links planejados" value={pipeline.internalLinks.filter(link => link.sourceArticleId === articleId).length}/><Field label="Fontes externas" value={pipeline.externalSources.filter(source => source.articleId === articleId).length}/><Field label="Status" value="Rascunho local; Tiptap pendente"/></dl><h3 className="mt-4 text-[9px] font-bold uppercase text-slate-600">Outline</h3>{document.blocks.filter(block => block.type === "heading").map(block => <button key={block.id} className="mt-1 block text-left text-[10px] text-slate-400">{"level" in block ? `H${block.level}` : ""} {"text" in block ? block.text : ""}</button>)}</aside>}
    <article className="min-h-[calc(100vh-180px)] w-full rounded-sm bg-white px-12 py-10 text-slate-900 shadow-2xl" aria-label="Documento editorial estruturado">{document.blocks.map(block => <ContentBlockView key={block.id} block={block}/>)}</article>
    {rightOpen && <aside className="h-fit rounded border border-slate-800 bg-[#090a0e] p-3"><h2 className="text-[10px] font-bold uppercase text-slate-500">Guardião por seção</h2><div className="mt-3 space-y-2">{pipeline.guardianFindings.filter(finding => finding.documentId === document.id).map(finding => <button key={finding.id} className="w-full rounded border border-amber-900/50 p-2 text-left text-[10px]" onClick={() => globalThis.document.getElementById(finding.sectionId)?.scrollIntoView({ behavior: "smooth", block: "center" })}><strong className="text-amber-400">{finding.category} · {finding.severity}</strong><p>{finding.message}</p><p className="text-slate-500">{finding.suggestion}</p></button>)}{["Cobertura semântica", "Intenção e entidades", "Naturalidade e repetição", "Canibalização", "Links e âncoras", "Fontes e YMYL", "E-E-A-T", "Aderência ao plano"].map(item => <div key={item} className="rounded border border-slate-800 p-2 text-[10px] text-slate-500">{item}: aguardando análise</div>)}</div><div className="mt-3 border-t border-slate-850 pt-3"><Field label="Slug" value={publication?.slug}/><Field label="Canonical" value="Não informado"/><Field label="Indexação" value="Controlada apenas no destino futuro"/></div><button className={`${btn} mt-3`} onClick={() => router.push(`/publicacoes?articleId=${articleId}`)}>Abrir em Publicações</button></aside>}
  </main></div>;
}

function ContentBlockView({ block }: { block: ContentDocument["blocks"][number] }) {
  return <section id={block.id} className="group relative mb-5 border-l-2 border-transparent pl-2 hover:border-indigo-300">{block.type === "heading" && (block.level === 1 ? <h1 className="text-3xl font-bold">{block.text}</h1> : block.level === 2 ? <h2 className="text-2xl font-bold">{block.text}</h2> : <h3 className="text-xl font-bold">{block.text}</h3>)}{block.type === "paragraph" && <p className="leading-7">{block.text}</p>}{block.type === "list" && (block.ordered ? <ol className="list-decimal pl-6">{block.items.map(item => <li key={item}>{item}</li>)}</ol> : <ul className="list-disc pl-6">{block.items.map(item => <li key={item}>{item}</li>)}</ul>)}{block.type === "table" && <table className="w-full border-collapse">{[block.headers, ...block.rows].map((row, index) => <tr key={index}>{row.map(cell => <td key={cell} className="border p-2">{cell}</td>)}</tr>)}</table>}{block.type === "quote" && <blockquote className="border-l-4 pl-3 italic">{block.text}</blockquote>}{block.type === "CTA" && <div className="rounded border border-indigo-200 bg-indigo-50 p-3"><strong>CTA</strong><p>{block.text}</p></div>}{block.type === "internal_link" && <p>Link interno: <u>{block.anchor}</u></p>}{block.type === "external_source" && <p>Fonte externa: {block.claim} · {block.url || "URL pendente"}</p>}{block.type === "image_brief" && <div className="rounded border border-dashed p-3">Imagem: {block.objective}</div>}{block.type === "note" && <aside className="rounded bg-amber-50 p-3">Nota: {block.text}</aside>}{block.type === "source" && <p className="text-sm">Fonte: {block.note}</p>}{block.type === "product_block" && <div className="rounded border p-3"><strong>{block.title}</strong><p>{block.summary}</p></div>}{block.type === "comparison" && <div className="rounded border p-3"><strong>{block.title}</strong></div>}<div className="mt-2 opacity-0 transition-opacity group-hover:opacity-100"><ProvenancePanel keywordRefs={block.provenance.keywordDnaRefs} evidenceRefs={block.provenance.evidenceRefs} sourceIds={block.provenance.sourceIds}/></div></section>;
}

type PublicationRow = OperationalPublication & { source: "workflow" } | { id: string; brandId: string; articleId: string; plannerItemId: string; contentPlanVersionId: string; documentId: string; title: string; slug: string; siloId: string; hierarchy: string; state: "published" | "approved"; responsible: string | null; destination: string | null; createdAt: string; updatedAt: string; origin: "real"; source: "briefing" };
export function PublicationsPage() {
  const { data: session } = useSession();
  const { selectedBrandId } = useBrand();
  const { pipeline, state } = useReadyPipeline();
  const [tab, setTab] = useState("library");
  const [picker, setPicker] = useState(false);
  const [notice, setNotice] = useState("");
  const historyValue = useMemo(() => ({ operationalPublications: pipeline.operationalPublications }), [pipeline.operationalPublications]);
  const history = useLocalHistory("publicacoes", historyValue, snapshot => pipeline.restoreOperationalSnapshot("publicacoes", snapshot), 30, selectedBrandId || "sem-marca");
  if (state || !pipeline.snapshot) return state;
  const approvedWriter = pipeline.operationalPublications.filter(item => ["approved", "ready_to_export", "queued", "exported", "published"].includes(item.state)).map(item => ({ ...item, alreadyImported: item.state !== "approved" }));
  const real: PublicationRow[] = pipeline.snapshot.briefings.map(item => ({ id: `briefing:${item.id}`, brandId: selectedBrandId, articleId: item.id, plannerItemId: "", contentPlanVersionId: "", documentId: "", title: item.titulo || item.keyword_principal, slug: item.slug_sugerido || "", siloId: item.silo_id, hierarchy: item.hierarquia || "", state: item.status?.toLowerCase() === "publicado" ? "published" : "approved", responsible: null, destination: item.canonical, createdAt: item.created_at || new Date(0).toISOString(), updatedAt: item.updated_at || item.created_at || new Date(0).toISOString(), origin: "real", source: "briefing" }));
  const imported: PublicationRow[] = pipeline.operationalPublications.filter(item => !["draft", "writing", "awaiting_review", "in_review", "approved"].includes(item.state)).map(item => ({ ...item, source: "workflow" }));
  const all = [...imported, ...real.filter(item => item.state === "published")];
  const rows = all.filter(item => tab === "published" ? item.state === "published" : tab === "queue" ? ["ready_to_export", "queued", "exported"].includes(item.state) : tab === "updates" ? item.state === "update_due" : !["published", "update_due", "queued", "exported"].includes(item.state));
  const columns: OperationalGridColumn<PublicationRow>[] = [
    { id: "title", header: "Artigo", value: row => row.title, pinned: "left", sortable: true, width: 250 },
    { id: "slug", header: "Slug", value: row => row.slug, width: 190, render: row => <code>/{row.slug}</code> },
    { id: "siloId", header: "Silo", value: row => row.siloId, sortable: true },
    { id: "hierarchy", header: "Hierarquia", value: row => row.hierarchy },
    { id: "version", header: "Versão", value: row => row.contentPlanVersionId || "legado" },
    { id: "keywordDnas", header: "KeywordDNAs", value: row => pipeline.contentPlans[`plan:${row.articleId}`]?.payload.keywordDnaRefs.length || (row.source === "briefing" ? "legado" : 0), width: 105 },
    { id: "articleDna", header: "ArticleDNA", value: row => pipeline.contentPlans[`plan:${row.articleId}`]?.payload.articleDnaRef.versionId || (row.source === "briefing" ? "legado" : "ausente"), width: 120 },
    { id: "siloDna", header: "SiloDNA", value: row => pipeline.contentPlans[`plan:${row.articleId}`]?.payload.siloDnaRef.versionId || (row.source === "briefing" ? "legado" : "ausente"), width: 120 },
    { id: "responsible", header: "Responsável", value: row => row.responsible || "não atribuído" },
    { id: "state", header: "Status", value: row => row.state, render: row => <WorkflowStatusBadge status={row.state}/>, sortable: true, width: 180 },
    { id: "destination", header: "Destino", value: row => row.destination || "não definido", width: 180 },
    { id: "updatedAt", header: "Última edição", value: row => new Date(row.updatedAt).toLocaleString("pt-BR"), sortable: true, width: 160 },
  ];
  const importApproved = (ids: string[]) => { history.capture(`Importar ${ids.length} artigo(s) do Redator`); const result = pipeline.importApprovedToPublications(ids); setNotice(`${result.imported} artigo(s) importado(s); ${result.skipped} ignorado(s).`); setPicker(false); };
  return <div className="flex h-screen min-h-0 flex-col">
    {notice && <div className="shrink-0 border-b border-amber-900/40 bg-amber-950/20 px-3 py-1.5 text-[9px] text-amber-300">{notice}</div>}
    <OperationalDataGrid title="Publicações" description="Artigos completos recebidos do Redator, sem envio automático ao CMS." module={`publicacoes:${tab}`} userId={sessionId(session)} brandId={selectedBrandId} rows={rows} columns={columns} toolbar={<><HistoryControls entries={history.entries} canUndo={history.canUndo} canRedo={history.canRedo} onUndo={history.undo} onRedo={history.redo} onRestore={history.restore} compact/>{[["library", "Biblioteca"], ["queue", "Fila"], ["published", "Publicados"], ["updates", "Atualizações"]].map(([id, label]) => <button key={id} className={`${btn} ${tab === id ? "border-indigo-500 text-white" : ""}`} onClick={() => setTab(id)}>{label}</button>)}<button className={btn} onClick={() => setPicker(true)}><Plus className="mr-1 h-3 w-3"/>Importar do Redator</button><button className={btn} onClick={() => void pipeline.reload()}><RefreshCw className="mr-1 h-3 w-3"/>Atualizar</button></>} emptyTitle="Nenhum conteúdo importado nesta aba." renderActions={row => row.documentId ? <Link href={`/redator?articleId=${row.articleId}`} className={btn}>{row.state === "published" ? "Reeditar" : "Abrir no Redator"}</Link> : <span className="text-[9px] text-slate-600">Documento local ausente</span>} renderExpanded={row => <div className="grid gap-3 md:grid-cols-4"><Field label="Artigo" value={row.articleId}/><Field label="KeywordDNAs" value={pipeline.contentPlans[`plan:${row.articleId}`]?.payload.keywordDnaRefs.length}/><Field label="ArticleDNA" value={pipeline.contentPlans[`plan:${row.articleId}`]?.payload.articleDnaRef.versionId}/><Field label="SiloDNA" value={pipeline.contentPlans[`plan:${row.articleId}`]?.payload.siloDnaRef.versionId}/><Field label="ContentPlan" value={row.contentPlanVersionId}/><Field label="ContentDocument" value={row.documentId}/><Field label="Origem" value={row.origin}/><Field label="Destino" value={row.destination}/><Field label="Estado" value={row.state}/></div>}/>
    <WorkflowImportDialog open={picker} title="Importar artigos aprovados do Redator" description="Todos os documentos aprovados aparecem aqui. Os já importados em Publicações permanecem visíveis e bloqueados." rows={approvedWriter} label={item => item.title} details={item => <span className="mt-1 block text-slate-500">/{item.slug} · {item.hierarchy}</span>} disabled={item => item.alreadyImported} status={item => item.alreadyImported ? item.state : "approved"} onClose={() => setPicker(false)} onImport={importApproved}/>
  </div>;
}

export function LegacyPublicationsPage() {
  const { data: session } = useSession(); const { selectedBrandId } = useBrand(); const { pipeline, state } = useReadyPipeline(); const [tab, setTab] = useState("library"); if (state || !pipeline.snapshot) return state;
  const real: PublicationRow[] = pipeline.snapshot.briefings.map(item => ({ id: `briefing:${item.id}`, brandId: selectedBrandId, articleId: item.id, plannerItemId: "", contentPlanVersionId: "", documentId: "", title: item.titulo || item.keyword_principal, slug: item.slug_sugerido || "", siloId: item.silo_id, hierarchy: item.hierarquia || "", state: item.status?.toLowerCase() === "publicado" ? "published" : "approved", responsible: null, destination: item.canonical, createdAt: item.created_at || new Date(0).toISOString(), updatedAt: item.updated_at || item.created_at || new Date(0).toISOString(), origin: "real", source: "briefing" }));
  const local: PublicationRow[] = pipeline.operationalPublications.map(item => ({ ...item, source: "workflow" })); const all = [...local, ...real];
  const rows = all.filter(item => tab === "published" ? item.state === "published" : tab === "queue" ? ["ready_to_export", "queued", "exported"].includes(item.state) : tab === "updates" ? item.state === "update_due" : !["published", "update_due", "ready_to_export", "queued", "exported"].includes(item.state));
  const columns: OperationalGridColumn<PublicationRow>[] = [
    { id: "title", header: "Artigo", value: row => row.title, pinned: "left", sortable: true, width: 250 }, { id: "slug", header: "Slug", value: row => row.slug, width: 190, render: row => <code>/{row.slug}</code> },
    { id: "siloId", header: "Silo", value: row => row.siloId, sortable: true }, { id: "hierarchy", header: "Hierarquia", value: row => row.hierarchy }, { id: "version", header: "Versão", value: row => row.contentPlanVersionId || "legado" },
    { id: "responsible", header: "Responsável", value: row => row.responsible || "não atribuído" }, { id: "seo", header: "SEO", value: () => "pendente" }, { id: "originality", header: "Originalidade", value: () => "pendente" },
    { id: "links", header: "Links", value: row => pipeline.internalLinks.filter(link => link.sourceArticleId === row.articleId).length }, { id: "sources", header: "Fontes", value: row => pipeline.externalSources.filter(source => source.articleId === row.articleId).length },
    { id: "state", header: "Status", value: row => row.state, render: row => <WorkflowStatusBadge status={row.state}/>, sortable: true, filterOptions: [...new Set(all.map(item => item.state))].map(value => ({ label: value, value })), width: 180 }, { id: "destination", header: "Destino", value: row => row.destination || "não definido", width: 180 },
    { id: "updatedAt", header: "Última edição", value: row => new Date(row.updatedAt).toLocaleString("pt-BR"), sortable: true, width: 160 },
  ];
  return <div className="flex h-screen min-h-0 flex-col"><ModuleHeader title="Publicações" description="Biblioteca, fila, publicados e atualizações — sem envio ao CMS."/><div className="flex gap-1 border-b border-slate-850 p-2">{[["library", "Biblioteca"], ["queue", "Fila"], ["published", "Publicados"], ["updates", "Atualizações"]].map(([id, label]) => <button key={id} className={`${btn} ${tab === id ? "border-indigo-500 text-white" : ""}`} onClick={() => setTab(id)}>{label}</button>)}</div><OperationalDataGrid module={`publicacoes:${tab}`} userId={sessionId(session)} brandId={selectedBrandId} rows={rows} columns={columns} emptyTitle="Nenhum conteúdo nesta aba." renderActions={row => row.documentId ? <Link href={`/redator?articleId=${row.articleId}`} className={btn}>{row.state === "published" ? "Reeditar" : "Abrir no Redator"}</Link> : <span className="text-[9px] text-slate-600">Documento local ausente</span>} renderExpanded={row => <div className="grid gap-3 md:grid-cols-4"><Field label="Artigo" value={row.articleId}/><Field label="ContentPlan" value={row.contentPlanVersionId}/><Field label="ContentDocument" value={row.documentId}/><Field label="Origem" value={row.origin}/><Field label="Destino" value={row.destination}/><Field label="Estado" value={row.state}/></div>}/></div>;
}

export function AccountPage() {
  const { data: session } = useSession(); return <><ModuleHeader title="Conta" description="Identidade e segurança separadas da empresa."/><main className="p-4"><div className="grid gap-3 md:grid-cols-2"><section className={card}><h2 className="text-xs font-bold">Dados pessoais</h2><dl className="mt-3 space-y-2"><Field label="Nome" value={session?.user?.name}/><Field label="E-mail" value={session?.user?.email}/><Field label="Foto" value={session?.user?.image ? "Disponível" : "Não informada"}/></dl></section><section className={card}><h2 className="text-xs font-bold">Autenticação e segurança</h2><p className="mt-3 text-[10px] text-slate-500">Senha, sessões, MFA e preferências pessoais ainda não possuem alteração nesta aplicação.</p><div className="mt-3 rounded border border-slate-800 p-2 text-[10px] text-slate-600">Visualizações salvas ficam temporariamente no navegador, separadas por usuário, marca e módulo. Nenhuma alteração de marca pode ser realizada por esta área.</div></section></div></main></>;
}

export function AdminOverviewPage() {
  const { brands } = useBrand(); return <><ModuleHeader title="Admin" description="Controle da plataforma, empresas e acessos delegados." actions={<Link href="/admin/marcas" className={btn}><Plus className="mr-1 h-3 w-3"/>Cadastrar nova marca</Link>}/><main className="p-4"><div className="grid gap-3 md:grid-cols-4"><Metric label="Empresas administradas" value={brands.length}/><Metric label="Acessos delegados" value={0}/><Metric label="Alertas" value={0}/><Metric label="Falhas" value={0}/></div><div className="mt-3 grid gap-3 md:grid-cols-3">{["Empresas e delegações", "Convites, usuários e permissões", "Consumo, cobrança e limites", "Atividades recentes", "Erros de processamento", "Status dos fluxos"].map(item => <section key={item} className={card}><h2 className="text-xs font-bold">{item}</h2><p className="mt-2 text-[10px] text-slate-600">Sem persistência operacional aplicada.</p></section>)}</div><Link href="/admin/marcas" className={`${btn} mt-4`}>Abrir cadastro existente <ExternalLink className="ml-1 h-3 w-3"/></Link></main></>;
}

function Metric({ label, value }: { label: string; value: unknown }) { return <div className={card}><p className="text-[8px] font-bold uppercase tracking-wider text-slate-600">{label}</p><p className="mt-2 text-xl font-black text-white">{String(value)}</p></div>; }
function LocalCollection({ title, count, description }: { title: string; count: number; description: string }) { return <section className={card}><h2 className="text-xs font-bold">{title}</h2><p className="mt-2 text-2xl font-black text-white">{count}</p><p className="mt-2 text-[10px] text-slate-600">{description}</p></section>; }
